dtsPropsFor.Pestanas:
/** Las pestañas, en orden: `id` estable, texto y, si se da, el número de la burbuja (con 0 queda vacía). */
pestanas: Array<{ id: string; etiqueta: string; contador?: number }>;
/** `id` de la pestaña seleccionada. */
activa: string;
/** Recibe el `id` de la pestaña pulsada. */
onCambiar: (id: string) => void;
className?: string;

dtsPropsFor.Filtros:
/** Las opciones, en orden: `id` estable y texto. */
opciones: Array<{ id: string; etiqueta: string }>;
/** `id` de la opción seleccionada. */
valor: string;
/** Recibe el `id` de la opción pulsada. */
onCambiar: (id: string) => void;
/** Nombre del grupo para lectores de pantalla («Cuándo»). */
etiqueta?: string;

dtsPropsFor.FilaCombate:
/** Identificador estable del combate; solo sirve de `key` cuando se pintan varias filas. */
id?: string;
/** Hora estimada ya formateada («17:30»), o «--:--» si no se sabe. */
hora: string;
/** Rival («vs Ana Pérez») o los dos contendientes («Ana Pérez vs Luis Gómez»). */
titulo: string;
/** Día corto («sáb 17»). */
dia?: string;
/** Si el día va en una `Etiqueta` (por defecto) o como texto corrido. */
diaComo?: "etiqueta" | "texto";
/** Gi o No-Gi, cuando el seguimiento junta dos eventos. */
evento?: string;
/** Resto de la segunda línea: «Semifinal · Tatami 3», o la categoría. */
detalle?: string;
/** Estado a la derecha: «EN CURSO», «Ganó · puntos»… El tono es el de `Etiqueta`. */
resultado?: { texto: string; tono?: "neutro" | "vivo" | "ganado" | "perdido" | "grupo" | "evento" };

dtsPropsFor.TarjetaProximo:
/** Hora estimada ya formateada («17:30»). */
hora: string;
/** El atleta al que sigues. */
nombre: string;
/** Su rival, o «Por determinar». */
rival: string;
/** Día corto («sáb 17»). */
dia?: string;
/** Gi o No-Gi, cuando el seguimiento junta dos eventos. */
evento?: string;
/** Tatami donde le toca. */
tatami?: string;
/** «EN CURSO» o «Pendiente». El tono es el de `Etiqueta`. */
resultado?: { texto: string; tono?: "neutro" | "vivo" | "ganado" | "perdido" | "grupo" | "evento" };

dtsPropsFor.TarjetaTatami:
/** Nombre del tatami («Mat 3»). */
nombre: string;
/** Resumen bajo el nombre («12 combates · 1 en curso»). */
resumen: string;
/** Lo que está en curso y lo que viene, en orden; unos pocos. Mismas props que `FilaCombate`. */
combates: Array<{ id?: string; hora: string; titulo: string; dia?: string; diaComo?: "etiqueta" | "texto"; evento?: string; detalle?: string; resultado?: { texto: string; tono?: "neutro" | "vivo" | "ganado" | "perdido" | "grupo" | "evento" } }>;
/** Retransmisión del tatami (`https://…`). */
transmision?: string;

dtsPropsFor.TarjetaAtleta:
/** Identificador del atleta (nombre + club); sale como `data-atleta` y `data-seguir`. */
id: string;
nombre: string;
club?: string;
/** Una categoría («Men's GI / Brown / Master 1 / 62KG»). */
categoria?: string;
/** Dirección de la foto; sin ella, un círculo vacío. */
foto?: string;
/** Mejor medalla conseguida hasta ahora. */
medalla?: "oro" | "plata" | "bronce";
/** Explica por qué está en la lista alguien a quien no has seguido tú. */
delGrupo?: boolean;
/** Tú lo sigues: el botón dice «Siguiendo» y se rellena. */
siguiendo: boolean;
onSeguir: () => void;
/** Al tocar el nombre (abre su ficha). */
onAbrir?: () => void;
/** Sus combates, mismas props que `FilaCombate`. Con la lista (aunque vacía) se pinta la sección. */
combates?: Array<{ id?: string; hora: string; titulo: string; dia?: string; diaComo?: "etiqueta" | "texto"; evento?: string; detalle?: string; resultado?: { texto: string; tono?: "neutro" | "vivo" | "ganado" | "perdido" | "grupo" | "evento" } }>;
/** Enlaces a sus cuadros en Smoothcomp (`https://…`). */
llaves?: Array<{ url: string; texto: string }>;
/** Solo en el panel del servidor: botón para que lo vea todo el grupo. */
paraTodos?: { activo: boolean; guardando?: boolean; onAlternar: () => void };

dtsPropsFor.ListaGrupo:
/** Quién está apuntado: `club` ya resuelto («sin club» si no hay) y si aún no tiene combates. */
entradas: Array<{ id: string; nombre: string; club: string; sinCombates: boolean }>;
/** Pulsar «Quitar»; el botón queda bloqueado hasta que termina. */
onQuitar: (id: string) => Promise<void> | void;
